#include <algorithm>
#include <string>

bool queryBuilder(std::string text, std::string query) {
    std::transform(text.begin(), text.end(), text.begin(), ::tolower);
    std::transform(query.begin(), query.end(), query.begin(), ::tolower);
    return text.find(query) != std::string::npos;
}
